// Stop gracefully pauses all in-flight snapshots at the current batch boundary and waits for them to exit.
func (r *SnapshotRunner) Stop() {
	r.stopping.Store(true)
	done := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(10 * time.Second):
		r.stopMu.Lock()
		if r.stopCancel != nil {
			r.stopCancel()
		}
		r.stopMu.Unlock()
		<-done
	}
}

