func (td *TableDebouncer) drainRemainingOnStop() {
	for {
		select {
		case batch := <-td.flushCh:
			if len(batch) > 0 {
				td.runTransmute(context.Background(), batch)
			}
		default:
			td.mu.Lock()
			tasks := td.tasks
			td.tasks = nil
			td.pendingEvents = 0
			if td.idleTimer != nil {
				td.idleTimer.Stop()
				td.idleTimer = nil
			}
			if td.maxTimer != nil {
				td.maxTimer.Stop()
				td.maxTimer = nil
			}
			td.mu.Unlock()
			if len(tasks) > 0 {
				td.runTransmute(context.Background(), tasks)
			}
			return
		}
	}
}

